using pmbridge::P;using pmbridge::Runtime;
struct Animation { uint32_t go=0,texture=0; P player=nullptr,raw=nullptr; std::string id,path; bool started=false,failed=false; };
namespace { Runtime*runtime=nullptr; std::set<std::string>played; std::vector<Animation>animations;
void logf(const char*fmt,...){char b[768];va_list a;va_start(a,fmt);vsnprintf(b,sizeof(b),fmt,a);va_end(a);PMDiagnosticsWrite(b);}
P target(Runtime&r,uint32_t h){return h?r.gchandle_get_target(h):nullptr;}
NSString*slotName(int slot){return @[@"EZ",@"HD",@"IN",@"AT"][std::clamp(slot,0,3)];}
NSDictionary*entity(NSString*id){NSDictionary*db=[PMContentStore.shared snapshot];for(NSDictionary*s in db[@"songs"])if([s[@"id"] isEqualToString:id])return s;for(NSDictionary*c in db[@"chapters"])if([c[@"id"] isEqualToString:id])return c;return nil;}
NSDictionary*ruleFor(NSString*id){return entity(id)[@"unlock"];}
P record(Runtime&r,NSString*id,int slot){try{return r.call(r.mainGame(),"GetSongRecord",{"System.String","System.String"},{r.managedString(id),r.managedString(slotName(slot))});}catch(...){return nullptr;}}
double rksValue(Runtime&r){try{P gi=r.mainGame();P boxed=r.call(gi,"get_RankingScore");return r.unbox<float>(boxed);}catch(...){return -1;}}
bool recordPass(Runtime&r,NSDictionary*c){NSString*type=c[@"type"],*ref=c[@"ref"];int slot=[c[@"slot"] respondsToSelector:@selector(intValue)]?[c[@"slot"] intValue]:-1;if([type isEqualToString:@"rks"])return rksValue(r)+1e-6>=[c[@"value"] doubleValue];if(!ref.length)return NO;if([type isEqualToString:@"chapter"]){NSDictionary*chapter=entity(ref);if(!chapter)return NO;for(NSString*sid in chapter[@"songs"]){NSDictionary*song=entity(sid);int from=slot<0?0:slot,to=slot<0?3:slot;for(int s=from;s<=to;++s){if(!song)return NO;int songSlot=[[@[@"EZ",@"HD",@"IN",@"AT"] objectAtIndex:s] isEqualToString:song[@"level"]]?s:-1;if(songSlot<0)continue;P rec=record(r,sid,s);if(!rec||r.get<int>(rec,"s")<=0)return NO;NSDictionary*m=[c mutableCopy];NSMutableDictionary*copy=[m mutableCopy];copy[@"type"]=@"score";copy[@"value"]=c[@"value"] ?: @700000;if(!recordPass(r,copy))return NO;}}return YES;}
int from=slot<0?0:slot,to=slot<0?3:slot;double threshold=[c[@"value"] doubleValue];for(int s=from;s<=to;++s){NSDictionary*custom=entity(ref);if(custom&&[custom[@"level"] isKindOfClass:NSString.class]&&![[custom[@"level"] uppercaseString] isEqualToString:slotName(s)])continue;P rec=record(r,ref,s);if(!rec)continue;int score=r.get<int>(rec,"s"),combo=r.get<int>(rec,"c");float acc=r.get<float>(rec,"a");bool pass=([type isEqualToString:@"score"]&&score>=threshold)||([type isEqualToString:@"acc"]&&std::isfinite(acc)&&acc+1e-6>=threshold)||([type isEqualToString:@"fc"]&&(combo==1||score==1000000))||([type isEqualToString:@"phi"]&&score==1000000);if(pass)return YES;}return NO;}
bool passes(Runtime&r,NSDictionary*rule){if(![rule[@"enabled"] boolValue])return YES;NSArray*conditions=rule[@"conditions"];if(![conditions isKindOfClass:NSArray.class]||!conditions.count)return NO;BOOL any=[rule[@"mode"] isEqualToString:@"any"];for(NSDictionary*c in conditions){BOOL pass=[c isKindOfClass:NSDictionary.class]&&recordPass(r,c);if(any&&pass)return YES;if(!any&&!pass)return NO;}return !any;}
void clearList(Runtime&r,P list){if(list)try{r.call(list,"Clear");}catch(...){} }
void unlockSong(Runtime&r,P value,NSString*id,int slot){if(!value||!([[[PMSettings shared] value:@"mainlineUnlock"] boolValue]||passes(r,ruleFor(id))))return;P unlocks=r.get<P>(value,"unlockInfo");int n=r.count(unlocks);for(int i=0;i<n;++i){P u=r.at(unlocks,i);r.put(u,"unlockType",-1);clearList(r,r.get<P>(u,"unlockInfo"));} }
void startAnimation(Runtime&r,NSString*id){if(!PMSettingBool("unlockAnimation"))return;NSDictionary*rule=ruleFor(id);NSString*name=rule[@"animation"];if(!name.length||![name.pathExtension.lowercaseString isEqualToString:@"mp4"])return;std::string key=[NSString stringWithFormat:@"%@/%@",id,name].UTF8String;if(!played.insert(key).second)return;NSString*folder=[PMContentStore.shared asset:id],*path=[[folder stringByAppendingPathComponent:name]stringByStandardizingPath];if(![path hasPrefix:[folder stringByAppendingString:@"/"]]||![NSFileManager.defaultManager fileExistsAtPath:path]){logf("Unlock animation missing for %s",id.UTF8String);return;}try{P go=r.object_new(r.type("UnityEngine","GameObject"));r.call(go,".ctor",{"System.String"},{r.string_new("PhiMod_UnlockAnimation")});uint32_t gh=r.gchandle_new(go,false);P canvas=r.call(go,"AddComponent",{"System.Type"},{r.type_get_object(r.class_get_type(r.type("UnityEngine","Canvas")))});int mode=0,order=30000;bool yes=true,no=false;r.call(canvas,"set_renderMode",{"UnityEngine.RenderMode"},{&mode});r.call(canvas,"set_overrideSorting",{"System.Boolean"},{&yes});r.call(canvas,"set_sortingOrder",{"System.Int32"},{&order});P raw=r.call(go,"AddComponent",{"System.Type"},{r.type_get_object(r.class_get_type(r.type("UnityEngine.UI","RawImage")))});r.call(raw,"set_raycastTarget",{"System.Boolean"},{&no});P tex=r.object_new(r.type("UnityEngine","RenderTexture"));int w=960,h=540,d=0;r.call(tex,".ctor",{"System.Int32","System.Int32","System.Int32"},{&w,&h,&d});r.call(tex,"Create");uint32_t th=r.gchandle_new(tex,false);r.call(raw,"set_texture",{"UnityEngine.Texture"},{tex});P player=r.call(go,"AddComponent",{"System.Type"},{r.type_get_object(r.class_get_type(r.type("UnityEngine.Video","VideoPlayer")))});bool wait=true,loop=false;r.call(player,"set_playOnAwake",{"System.Boolean"},{&loop});r.call(player,"set_isLooping",{"System.Boolean"},{&loop});r.call(player,"set_waitForFirstFrame",{"System.Boolean"},{&wait});int render=2;r.call(player,"set_renderMode",{"UnityEngine.Video.VideoRenderMode"},{&render});r.call(player,"set_targetTexture",{"UnityEngine.RenderTexture"},{tex});NSURL*u=[NSURL fileURLWithPath:path];r.call(player,"set_url",{"System.String"},{r.managedString(u.absoluteString)});r.call(player,"Prepare");animations.push_back({gh,th,player,raw,key,path.UTF8String,false,false});}catch(const std::exception&e){logf("Unlock animation setup failed: %s",e.what());}}
}
void attach(Runtime&r){runtime=&r;}
void songInfo(Runtime&r,void*song,int slot,void*value){if(!runtime||!song)return;try{NSString*id=r.string(r.get<P>((P)song,"songsId"));if(id.length&&passes(r,ruleFor(id)))startAnimation(r,id);}catch(const std::exception&e){logf("Unlock song info failed: %s",e.what());}(void)slot;(void)value;}
void itemInfo(Runtime&r,void*item,int slot,void*value){if(!runtime||!item)return;try{P info=r.get<P>((P)item,"songInfo");NSString*id=info?r.string(r.get<P>(info,"songsId")):nil;unlockSong(r,info,id,slot);if([[[PMSettings shared] value:@"mainlineUnlock"] boolValue]){r.put((P)item,"<Unlocked>k__BackingField",true);r.put((P)item,"unlockType",-1);r.put((P)item,"unlockInfo",r.managedString(@""));r.put((P)item,"visible",true);}if(id.length&&passes(r,ruleFor(id)))startAnimation(r,id);}catch(const std::exception&e){logf("Unlock item info failed: %s",e.what());}}
void chapterReady(Runtime&r,void*selector){if(!PMSettingBool("mainlineUnlock"))return;try{P cards=r.get<P>((P)selector,"_chapterInfos");for(uintptr_t i=0;cards&&i<r.array_length(cards);++i){P card=r.arrayAt(cards,(int)i),locked=r.get<P>(card,"locked"),play=r.get<P>(card,"play");if(r.alive(locked)){bool no=false;r.call(locked,"SetActive",{"System.Boolean"},{&no});}if(r.alive(play)){bool yes=true;r.call(play,"set_interactable",{"System.Boolean"},{&yes});}}}catch(const std::exception&e){logf("Mainline chapter unlock failed: %s",e.what());}}
void tick(Runtime&r,void*selector){for(size_t i=0;i<animations.size();){auto&a=animations[i];try{P player=a.player;if(!r.alive(player)){r.gchandle_free(a.go);r.gchandle_free(a.texture);animations.erase(animations.begin()+i);continue;}bool prepared=r.unbox<bool>(r.call(player,"get_isPrepared"));if(prepared&&!a.started){r.call(player,"Play");a.started=true;}if(a.started&&!r.unbox<bool>(r.call(player,"get_isPlaying"))){P go=target(r,a.go);if(r.alive(go))r.stat(r.type("UnityEngine","Object"),"Destroy",{"UnityEngine.Object"},{go});P tex=target(r,a.texture);if(r.alive(tex))r.stat(r.type("UnityEngine","Object"),"Destroy",{"UnityEngine.Object"},{tex});r.gchandle_free(a.go);r.gchandle_free(a.texture);animations.erase(animations.begin()+i);continue;}}catch(...){a.failed=true;}++i;} (void)selector;}
void clear(Runtime&r){for(auto&a:animations){P go=target(r,a.go);if(r.alive(go))try{r.stat(r.type("UnityEngine","Object"),"Destroy",{"UnityEngine.Object"},{go});}catch(...){}r.gchandle_free(a.go);r.gchandle_free(a.texture);}animations.clear();played.clear();}
